_td_transition() {
  local action=$1
  td_next_water=$td_water td_next_beds=$td_beds td_next_food=$td_food
  (( td_food < 12 )) || { _td_fail 'goal reached; this world is paused'; return 1; }
  case $action in
    collect) (( td_next_water += 3 ));;
    plant) (( td_next_water -= 2, td_next_beds += 1 ));;
    harvest) (( td_next_water -= 1, td_next_beds -= 1, td_next_food += 3 ));;
    *) _td_fail "unknown action: $action"; return 1;;
  esac
  (( td_next_water >= 2 && td_next_water <= 12 )) || {
    _td_fail "water must remain in [2,12]; $action would leave $td_next_water"; return 1
  }
  (( td_next_beds >= 0 && td_next_beds <= 3 )) || {
    _td_fail "beds must remain in [0,3]; $action would leave $td_next_beds"; return 1
  }
  (( td_next_food <= 12 )) || { _td_fail 'food goal would be exceeded'; return 1; }
  return 0
